const u = $json;
const ACTIONS = ["a", "e", "d", "c", "x", "qc", "qr", "u", "p", "n"];
let out = { kind: "OTHER", chat_id: null, callback_query_id: null, action: null, bundle_id: null, text: null };
if (u.callback_query) {
  const cq = u.callback_query;
  const data = String(cq.data || "");
  const i = data.indexOf(":");
  const action = i > 0 ? data.slice(0, i) : data;
  const bundleId = i > 0 ? data.slice(i + 1) : null;
  out.chat_id = cq.message && cq.message.chat ? String(cq.message.chat.id) : (cq.from ? String(cq.from.id) : null);
  out.callback_query_id = String(cq.id);
  if (ACTIONS.includes(action) && bundleId) { out.kind = "BUTTON"; out.action = action; out.bundle_id = bundleId; }
} else if (u.message) {
  out.chat_id = u.message.chat ? String(u.message.chat.id) : null;
  if (typeof u.message.text === "string" && u.message.text.trim()) { out.kind = "TEXT"; out.text = u.message.text.trim().slice(0, 1000); }
}
return { json: out };

const cfg = $('Config').first().json;
const n = $('Normalise').first().json;
const errText = e => e ? (typeof e === "object" ? (e.message || JSON.stringify(e)) : String(e)) : null;
const inErr = $input.first() && $input.first().json && $input.first().json.error;
const safeAll = name => { try { return $(name).all(0).map(i => i.json); } catch (e) { return []; } };
const sessRows = safeAll("Get Session").filter(r => r && r.telegram_chat_id);
const session = sessRows[0] || null;
const bRows = safeAll("Get Bundle").filter(r => r && r.bundle_id);
const bundle = bRows[0] || null;
const items = safeAll("Get Items").filter(r => r && r.bundle_id && r.date).sort((a, b) => String(a.date).localeCompare(String(b.date)));

const ALLOWED = {
  a: ["SENT", "APPLY_FAILED"],
  e: ["SENT", "AWAITING_CONFIRM", "DECLINED", "APPLIED", "UNDONE", "APPLY_FAILED"],
  d: ["SENT"],
  c: ["AWAITING_CONFIRM"],
  x: ["EDITING", "AWAITING_CONFIRM"],
  qc: ["SENT", "EDITING"],
  qr: ["SENT", "EDITING", "DECLINED", "UNDONE"],
  u: ["APPLIED", "APPLY_FAILED"],
  p: ["APPLIED", "UNDONE"],
  n: ["DECLINED", "APPLIED", "UNDONE"],
  PARSE: ["EDITING", "AWAITING_CONFIRM"],
};

// Edit session for this bundle, and the status the bundle had before the edit started.
const sessFor = (session && bundle && String(session.bundle_id) === String(bundle.bundle_id)) ? session : null;
const sessActive = !!(sessFor && ["AWAITING_EDIT_TEXT", "AWAITING_CONFIRM"].includes(sessFor.state) && sessFor.expires_at && new Date(sessFor.expires_at).getTime() > Date.now());
let pc = sessFor ? sessFor.pending_changes : null;
if (typeof pc === "string") { try { pc = JSON.parse(pc); } catch (e) { pc = null; } }
const heuristic = items.length && items.every(i => i.final_hours !== null && i.final_hours !== undefined && i.final_hours !== "") ? "APPLIED" : "SENT";
const storedFrom = (pc && !Array.isArray(pc) && typeof pc === "object") ? pc.from_status : null;
const fromStatus = (storedFrom && !["EDITING", "AWAITING_CONFIRM"].includes(storedFrom)) ? storedFrom : heuristic;
const EDIT_STATES = ["EDITING", "AWAITING_CONFIRM"];
let effStatus = bundle ? bundle.status : null;
let restoreStatus = null;
// APPLYING older than 10 minutes means the Apply run died mid-way: treat it as APPLY_FAILED so the owner can retry.
const STALE_APPLYING_MS = 10 * 60000;
if (bundle && bundle.status === "APPLYING" && (!bundle.updated_at || Date.now() - new Date(bundle.updated_at).getTime() > STALE_APPLYING_MS)) effStatus = "APPLY_FAILED";
if (bundle && EDIT_STATES.includes(bundle.status) && !sessActive) { effStatus = fromStatus; restoreStatus = fromStatus; }
const originStatus = sessActive ? fromStatus : effStatus;

let route;
let readError = null;
if (inErr && typeof inErr === "object") { route = "READ_ERROR"; readError = errText(inErr); }
else if (n.kind === "BUTTON") {
  route = (!bundle || String(bundle.telegram_chat_id) !== String(n.chat_id)) ? "UNKNOWN" : n.action;
} else if (n.kind === "TEXT") {
  route = (sessActive && String(bundle.telegram_chat_id) === String(n.chat_id)) ? "PARSE" : "HELP";
} else route = "HELP";

let allowed = true;
let abandonEdit = false;
if (ALLOWED[route]) {
  allowed = !!bundle && ALLOWED[route].includes(effStatus);
  if (!allowed && bundle && sessActive && ["u", "p", "n"].includes(route) && ALLOWED[route].includes(fromStatus)) { allowed = true; abandonEdit = true; }
}

return [{ json: {
  route,
  allowed,
  abandon_edit: abandonEdit,
  origin_status: originStatus,
  restore_status: route === "READ_ERROR" ? null : restoreStatus,
  read_error: readError,
  kind: n.kind,
  action: n.action,
  chat_id: n.chat_id,
  text: n.text,
  bundle,
  items,
  session,
  cfg: {
    TELEGRAM_STAFF_CHAT_ID: String(cfg.TELEGRAM_STAFF_CHAT_ID || ""),
    YEXT_BASE_URL: cfg.YEXT_BASE_URL,
    YEXT_VERSION: cfg.YEXT_VERSION,
    EDIT_SESSION_MINUTES: Number(cfg.EDIT_SESSION_MINUTES || 30),
    UNDO_WINDOW_HOURS: Number(cfg.UNDO_WINDOW_HOURS || 24),
  },
  today: $now.toISODate(),
} }];

const ctx = $('Resolve + State Guard').first().json;
let parsed = null;
try {
  if ($('Parse Edit').isExecuted) {
    let pi = null;
    try { pi = $('Parse Edit').first(0); } catch (e2) { pi = null; }
    const p = pi && pi.json;
    parsed = (p && p.intent) ? p : { intent: "UNCLEAR", changes: [], reason: "LLM_ERROR", parser: "LLM" };
  }
} catch (e) { parsed = null; }

const b = ctx.bundle || null;
const items = ctx.items || [];
const id = b ? b.bundle_id : null;
const lang = b && ["fi", "sv", "nb", "en"].includes(b.language) ? b.language : "en";
const chat = ctx.chat_id ? String(ctx.chat_id) : null;
const btn = (k, a) => ({ key: k, data: a + ":" + id });
const reply = (key, o) => ({ chat_id: chat, language: (o && o.language) || lang, text: null, key, params: (o && o.params) || {}, lines: (o && o.lines) || [], buttons: (o && o.buttons) || [], edit_message_id: null });
const display = h => h === null || h === undefined || h === "" ? "–" : h === "closed" ? "{@label_closed}" : h === "regular" ? "{@label_regular}" : String(h).split(",").map(x => x.trim().replace("-", "–")).join(", ");
const ddmm = d => { const p = String(d).split("-"); return Number(p[2]) + "." + Number(p[1]) + "."; };
const expires = new Date(Date.now() + ctx.cfg.EDIT_SESSION_MINUTES * 60000).toISOString();
const rawText = ctx.kind === "TEXT" ? ctx.text : (ctx.action ? ctx.action + ":" + (id || "") : null);

const plan = { bundle_id: id, chat_id: chat, item_updates: [], status: null, session: { op: "NONE" }, permission_entity: null, decision: null, replies: [], apply: null };
const decide = (action, parsedObj, parser) => {
  if (!id) return null;
  return { bundle_id: id, action, raw_text: rawText, parsed: parsedObj || null, parser: parser || (ctx.kind === "BUTTON" ? "BUTTON" : "SYSTEM") };
};

const origin = (!ctx.origin_status || ["EDITING", "AWAITING_CONFIRM"].includes(ctx.origin_status)) ? "SENT" : ctx.origin_status;

function confirmCard(changes, parser, action) {
  const map = {};
  changes.forEach(c => { map[c.date] = c.hours; });
  const lines = items.filter(i => map[i.date] !== undefined).map(i => "• " + (i.day_name || i.date) + ": " + display(i.shown_hours) + " → " + display(map[i.date]));
  plan.session = { op: "UPSERT", state: "AWAITING_CONFIRM", pending_changes: { from_status: origin, changes }, expires_at: expires };
  if (b.status !== "AWAITING_CONFIRM") plan.status = "AWAITING_CONFIRM";
  plan.replies.push(reply("msg_confirm_title", { lines, buttons: [btn("btn_confirm", "c"), btn("btn_edit", "e"), btn("btn_cancel", "x")] }));
  plan.decision = decide(action, { changes }, parser);
}

function cancelEdit() {
  plan.session = { op: "IDLE" };
  plan.status = origin;
  plan.replies.push(reply("msg_cancelled"));
  plan.decision = decide("CANCEL");
}

function decline(parser, parsedObj, fromText) {
  if (fromText && ["APPLIED", "UNDONE"].includes(origin)) { cancelEdit(); return; }
  plan.status = "DECLINED";
  if (ctx.session && String(ctx.session.bundle_id) === String(id)) plan.session = { op: "IDLE" };
  plan.replies.push(reply("msg_declined", { buttons: [btn("btn_regular", "qr"), btn("btn_edit", "e"), btn("btn_not_now", "n")] }));
  plan.decision = decide("DECLINE", parsedObj, parser);
}

if (ctx.route === "READ_ERROR") {
  if (chat) plan.replies.push(reply("msg_apply_failed"));
  plan.replies.push({ chat_id: ctx.cfg.TELEGRAM_STAFF_CHAT_ID, language: "en", text: null, key: "msg_staff_error",
    params: { business_name: b ? b.business_name : "?", entity_id: b ? b.entity_id : "?", bundle_id: id || "?", error: "Router read failed (nothing changed): " + ctx.read_error }, lines: [], buttons: [], edit_message_id: null });
} else if (!ctx.allowed) {
  plan.replies.push(reply("msg_already_handled"));
  plan.decision = decide("ALREADY_HANDLED", { route: ctx.route, status: b ? b.status : null });
} else {
  switch (ctx.route) {
    case "a":
      // Retry after a failed apply keeps the hours the owner already confirmed.
      plan.item_updates = items.map(i => ({ id: i.id, final_hours: (ctx.origin_status === "APPLY_FAILED" && i.final_hours) ? i.final_hours : i.proposed_hours }));
      plan.status = "APPROVED";
      plan.decision = decide("APPROVE", ctx.origin_status === "APPLY_FAILED" ? { retry_after: "APPLY_FAILED" } : null);
      plan.apply = { mode: "APPLY" };
      break;
    case "e":
      plan.status = "EDITING";
      plan.session = { op: "UPSERT", state: "AWAITING_EDIT_TEXT", pending_changes: { from_status: origin, changes: [] }, expires_at: expires };
      plan.replies.push(reply("msg_edit_prompt", { buttons: [btn("btn_closed", "qc"), btn("btn_regular", "qr"), btn("btn_cancel", "x")] }));
      plan.decision = decide("EDIT");
      break;
    case "qc":
      confirmCard(items.map(i => ({ date: i.date, hours: "closed" })), "BUTTON", "QUICK_CLOSED");
      break;
    case "qr":
      confirmCard(items.map(i => ({ date: i.date, hours: "regular" })), "BUTTON", "QUICK_REGULAR");
      break;
    case "PARSE":
      if (parsed && parsed.intent === "SET_CHANGES") confirmCard(parsed.changes, parsed.parser, "EDIT_TEXT");
      else if (parsed && parsed.intent === "DECLINE") decline(parsed.parser, parsed, true);
      else {
        const reason = parsed ? parsed.reason : "LLM_ERROR";
        const key = reason === "BAD_TIME" ? "msg_bad_time" : reason === "BAD_DATE" ? "msg_bad_date" : "msg_clarify";
        plan.replies.push(reply(key, { params: { dates: items.map(i => ddmm(i.date)).join(", ") }, buttons: [btn("btn_closed", "qc"), btn("btn_regular", "qr"), btn("btn_cancel", "x")] }));
        plan.decision = decide("UNCLEAR", parsed, parsed ? parsed.parser : "LLM");
      }
      break;
    case "c": {
      const s = ctx.session;
      let pending = s && String(s.bundle_id) === String(id) ? s.pending_changes : null;
      if (typeof pending === "string") { try { pending = JSON.parse(pending); } catch (e) { pending = null; } }
      if (pending && !Array.isArray(pending) && typeof pending === "object") pending = pending.changes;
      if (!Array.isArray(pending) || !pending.length) {
        plan.replies.push(reply("msg_already_handled"));
        plan.decision = decide("ALREADY_HANDLED", { reason: "NO_PENDING_CHANGES" });
        break;
      }
      const map = {};
      pending.forEach(p => { map[p.date] = p.hours; });
      plan.item_updates = items.map(i => ({ id: i.id, final_hours: map[i.date] !== undefined ? map[i.date] : i.proposed_hours }));
      plan.status = "APPROVED";
      plan.session = { op: "IDLE" };
      plan.decision = decide("CONFIRM", { changes: pending });
      plan.apply = { mode: "APPLY" };
      break;
    }
    case "x":
      cancelEdit();
      break;
    case "d":
      decline("BUTTON", null, false);
      break;
    case "u":
      plan.decision = decide("UNDO");
      plan.apply = { mode: "UNDO" };
      break;
    case "p":
      plan.permission_entity = b.entity_id;
      plan.replies.push(reply("msg_permission_granted"));
      plan.decision = decide("GRANT_PERMISSION");
      break;
    case "n":
      plan.decision = decide("NOT_NOW");
      break;
    case "UNKNOWN":
      if (chat) plan.replies.push(reply("msg_help", { language: "en" }));
      break;
    default:
      if (chat) plan.replies.push(reply("msg_help"));
      if (ctx.kind === "TEXT" && ctx.session && b) plan.decision = decide("HELP", null, "SYSTEM");
  }
  // Undo / permission / not now tapped during an open edit: close the edit, go back to the pre-edit status.
  if (ctx.abandon_edit) { plan.session = { op: "IDLE" }; if (!plan.status) plan.status = origin; }
}
// Edit session expired: put the bundle back to its pre-edit status instead of leaving it in EDITING.
if (ctx.restore_status && !plan.status && id) plan.status = ctx.restore_status;
return [{ json: plan }];

const expected = $('Plan').first().json.item_updates.length;
const rows = $input.all().map(i => i.json);
const errs = rows.filter(r => r && r.error).map(r => typeof r.error === "object" ? (r.error.message || JSON.stringify(r.error)) : String(r.error));
const done = rows.filter(r => r && r.id !== undefined && r.id !== null && !r.error).length;
return [{ json: { ok: done === expected && errs.length === 0, updated: done, expected, error: errs.length ? errs.join("; ") : (done === expected ? null : "updated " + done + " of " + expected + " items") } }];

const p = $('Plan').first().json;
return [{ json: {
  telegram_chat_id: String(p.chat_id),
  bundle_id: p.bundle_id,
  state: p.session.state,
  pending_changes: p.session.pending_changes || [],
  expires_at: p.session.expires_at,
  updated_at: new Date().toISOString(),
} }];

const p = $('Plan').first().json;
const ctx = $('Resolve + State Guard').first().json;
const b = ctx.bundle || {};
const errText = e => e ? (typeof e === "object" ? (e.message || JSON.stringify(e)) : String(e)) : null;
let failure = null;
try { if ($('Write Failed').isExecuted) failure = "Database write failed (Yext untouched): " + $('Write Failed').first().json.error; } catch (e) {}
let ownerKey = "msg_apply_failed";
let notifyStaff = true;
let applyRan = false;
try { applyRan = !failure && $('Run Apply').isExecuted; } catch (e) { applyRan = false; }
if (applyRan) {
  const r = $input.first().json || {};
  if (!r.status) failure = "Apply sub-workflow error: " + (errText(r.error) || "no result");
  else if (r.status === "SKIPPED_GUARD") {
    const reason = String(r.error || "UNKNOWN");
    if (reason.startsWith("STATUS_") || reason === "UNDO_WINDOW_EXPIRED") { ownerKey = "msg_already_handled"; notifyStaff = false; }
    failure = "Apply skipped by guard (Yext untouched): " + reason;
  } else {
    return [];
  }
}
if (failure) {
  const out = [];
  if (p.chat_id) out.push({ json: { chat_id: p.chat_id, language: b.language || "en", text: null, key: ownerKey, params: {}, lines: [], buttons: [], edit_message_id: null } });
  if (notifyStaff) out.push({ json: { chat_id: ctx.cfg.TELEGRAM_STAFF_CHAT_ID, language: "en", text: null, key: "msg_staff_error",
    params: { business_name: b.business_name || "?", entity_id: b.entity_id || "?", bundle_id: p.bundle_id || "?", error: failure }, lines: [], buttons: [], edit_message_id: null } });
  return out;
}
return p.replies.map(r => ({ json: r }));

const e = $input.first().json.error;
const msg = e ? (typeof e === "object" ? (e.message || JSON.stringify(e)) : String(e)) : "database write failed";
return [{ json: { write_failed: true, error: msg } }];
